settings.custom_liquid:
{%- assign current_variant = product.variants.first -%}

<div style="display: flex; align-items: center;">

  {% if current_variant.inventory_quantity > 0 and current_variant.inventory_management == 'shopify' %}
    <!-- 1. VOYANT VERT : En stock réel (Stock suivi actif ET Quantité > 0) -->
    <span class="svg-wrapper" style="color: rgb(62, 214, 96); display: flex; align-items: center;">
      {{- 'icon-inventory-status.svg' | inline_asset_content -}}
    </span>
    <span style="margin-left: 5px;">
      {{- 'products.product.inventory_in_stock_show_count' | t: quantity: current_variant.inventory_quantity -}}
    </span>

  {% elsif current_variant.inventory_management != 'shopify' %}
    <!-- 2. VOYANT ORANGE : Suivi inactif (Dispo fournisseur) -->
    <span class="svg-wrapper" style="color: rgb(238, 148, 65); display: flex; align-items: center;">
      {{- 'icon-inventory-status.svg' | inline_asset_content -}}
    </span>
    <span style="margin-left: 5px;">
      Disponible chez notre Fournisseur
    </span>

  {% else %}
    <!-- 3. VOYANT ROUGE : Rupture (Stock suivi actif ET Quantité <= 0) -->
    <span class="svg-wrapper" style="color: rgb(230, 0, 0); display: flex; align-items: center;">
      {{- 'icon-inventory-status.svg' | inline_asset_content -}}
    </span>
    <span style="margin-left: 5px;">
      Rupture de stock
    </span>

  {% endif %}
</div>
